<template>
  <div class="container">
    <header>
      <h1>Sistema de Diagnóstico de Prevenção de AVC</h1>
      <p class="subtitle">
        Apoio ao diagnóstico médico com inteligência artificial para resultados
        mais rápidos e precisos. Nossa tecnologia analisa imagens de
        tomografia computacional cerebral para identificar possíveis AVCs com alta
        precisão.
      </p>
    </header>

    <div class="content">
      <div class="upload-section">
        <!-- IMAGEM DE RESSONÂNCIA -->
        <div class="upload-box">
          <h2 class="upload-title">Imagem de Ressonância</h2>
          <div class="upload-area">
            <i class="fas fa-brain"></i>
            <p class="upload-text">Selecione o arquivo do exame de imagem</p>

            <!-- IMPORTANTE: chama onImageSelect -->
            <input type="file" accept="image/*" @change="onImageSelect" />
            <p v-if="imgSaved" style="color:#16a34a;margin-top:8px">Imagem salva.</p>
            <p v-if="imgError" style="color:#ef4444;margin-top:8px">{{ imgError }}</p>
          </div>
          <p>Formatos suportados: JPG, PNG</p>
        </div>

        <!-- FICHA DO PACIENTE -->
        <div class="upload-box">
          <h2 class="upload-title">Ficha do Paciente</h2>
          <div class="upload-area" style="padding:20px; text-align:left;">
            <label class="upload-text">Nome do Paciente</label>
            <input v-model="paciente.nome" type="text" placeholder="Digite o nome" class="form-input" />

            <label class="upload-text">Idade</label>
            <input v-model="paciente.idade" type="number" placeholder="Digite a idade" class="form-input" />

            <label class="upload-text">Data do Exame</label>
            <input v-model="paciente.dataExame" type="date" class="form-input" />

            <label class="upload-text">Médico Solicitante</label>
            <input v-model="paciente.medico" type="text" placeholder="Digite o nome do médico" class="form-input" />
          </div>
        </div>
      </div>

      <div style="text-align:center;">
        <!-- Salva dados e vai para a página 2 -->
        <a class="btn" href="/resultados.html" @click.prevent="salvarEDirecionar">Iniciar Análise com IA</a>
        <div class="note"></div>
      </div>
    </div>
  </div>
</template>

<script>
export default {
  name: "App",
  data() {
    return {
      paciente: {
        nome: "",
        idade: "",
        dataExame: "",
        medico: ""
      },
      imgSaved: false,
      imgError: ""
    };
  },
  methods: {
    async onImageSelect(e) {
      this.imgError = "";
      this.imgSaved = false;
      const file = e.target.files?.[0];
      if (!file) return;

      if (!file.type.startsWith("image/")) {
        this.imgError = "Selecione um arquivo de imagem (JPG/PNG).";
        return;
      }

      try {
        const dataURL = await this.readFileAsDataURL(file);
        const resized = await this.downscaleDataURL(dataURL, {
          maxW: 1200,
          maxH: 1200,
          quality: 0.85
        });
        localStorage.setItem("neuroscan_image", resized);
        this.imgSaved = true;
      } catch (err) {
        console.error(err);
        this.imgError = "Não foi possível salvar a imagem. Tente uma imagem menor.";
      }
    },

    readFileAsDataURL(file) {
      return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onerror = () => reject(new Error("Falha ao ler o arquivo."));
        reader.onload = () => resolve(reader.result);
        reader.readAsDataURL(file);
      });
    },

    downscaleDataURL(srcDataURL, { maxW = 1200, maxH = 1200, quality = 0.85 } = {}) {
      return new Promise((resolve, reject) => {
        const img = new Image();
        img.onload = () => {
          const ratio = Math.min(maxW / img.width, maxH / img.height, 1);
          const w = Math.round(img.width * ratio);
          const h = Math.round(img.height * ratio);

          const canvas = document.createElement("canvas");
          canvas.width = w;
          canvas.height = h;
          const ctx = canvas.getContext("2d");
          ctx.drawImage(img, 0, 0, w, h);

          const out = canvas.toDataURL("image/jpeg", quality);
          resolve(out);
        };
        img.onerror = () => reject(new Error("Falha ao processar a imagem."));
        img.src = srcDataURL;
      });
    },

    salvarEDirecionar() {
      // salva a ficha no localStorage
      localStorage.setItem("neuroscan_paciente", JSON.stringify(this.paciente));
      // redireciona para a página de resultados
      window.location.href = "/resultados.html";
    }
  }
};
</script>

